CREATE TABLE IF NOT EXISTS p1_coupons (id VARCHAR(64) PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, minimum_cents BIGINT NOT NULL, discount_cents BIGINT NOT NULL, capacity INT NOT NULL, active BOOLEAN NOT NULL, version INT NOT NULL DEFAULT 1, starts_at DATETIME(3) NOT NULL, ends_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p1_coupon_grants (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, coupon_id VARCHAR(64) NOT NULL, state VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE', order_id VARCHAR(64), created_at DATETIME(3) NOT NULL, UNIQUE(user_id,coupon_id), INDEX(order_id));
CREATE TABLE IF NOT EXISTS p1_campaigns (id VARCHAR(64) PRIMARY KEY, product_id VARCHAR(64) NOT NULL, title VARCHAR(100) NOT NULL, rate_bps INT NOT NULL, version INT NOT NULL, active BOOLEAN NOT NULL, created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p1_promotion_links (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, campaign_id VARCHAR(64) NOT NULL, campaign_version INT NOT NULL, product_id VARCHAR(64) NOT NULL, rate_bps INT NOT NULL, created_at DATETIME(3) NOT NULL, UNIQUE(user_id,campaign_id,campaign_version));
CREATE TABLE IF NOT EXISTS p1_order_benefits (order_id VARCHAR(64) PRIMARY KEY, coupon_grant_id VARCHAR(64), discount_cents BIGINT NOT NULL DEFAULT 0, promoter_id VARCHAR(64), rate_bps INT NOT NULL DEFAULT 0, campaign_version INT, settled BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS p1_commission_ledger (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, order_id VARCHAR(64) NOT NULL, event_key VARCHAR(100) NOT NULL UNIQUE, amount_cents BIGINT NOT NULL, kind VARCHAR(20) NOT NULL, created_at DATETIME(3) NOT NULL, INDEX(user_id));
CREATE TABLE IF NOT EXISTS p1_commission_settlements (order_id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, amount_cents BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, mode VARCHAR(20) NOT NULL, created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p1_invoices (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, order_id VARCHAR(64) NOT NULL UNIQUE, title VARCHAR(100) NOT NULL, tax_number VARCHAR(30) NOT NULL, amount_cents BIGINT NOT NULL, state VARCHAR(20) NOT NULL, invoice_number VARCHAR(100), review_reason VARCHAR(500), created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p1_documents (id VARCHAR(64) PRIMARY KEY, product_id VARCHAR(64) NOT NULL, title VARCHAR(150) NOT NULL, content MEDIUMTEXT NOT NULL, version INT NOT NULL, state VARCHAR(20) NOT NULL, author_id VARCHAR(64) NOT NULL, reviewer_id VARCHAR(64), review_reason VARCHAR(500), valid_until DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL, INDEX(state));
CREATE TABLE IF NOT EXISTS p1_knowledge_revision (id INT PRIMARY KEY, revision BIGINT NOT NULL);
INSERT IGNORE INTO p1_knowledge_revision VALUES(1,1);
CREATE TABLE IF NOT EXISTS p1_contacts (user_id VARCHAR(64) PRIMARY KEY, channel VARCHAR(12) NOT NULL, destination VARCHAR(150) NOT NULL, verified_at DATETIME(3) NOT NULL, UNIQUE(channel,destination));
CREATE TABLE IF NOT EXISTS p1_challenges (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64), purpose VARCHAR(20) NOT NULL, channel VARCHAR(12) NOT NULL, destination VARCHAR(150) NOT NULL, code_hash CHAR(64) NOT NULL, attempts INT NOT NULL DEFAULT 0, consumed BOOLEAN NOT NULL DEFAULT FALSE, expires_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL, INDEX(destination,created_at));
CREATE TABLE IF NOT EXISTS p1_deliveries (id VARCHAR(64) PRIMARY KEY, event_key VARCHAR(150) NOT NULL UNIQUE, user_id VARCHAR(64), channel VARCHAR(12) NOT NULL, destination VARCHAR(150) NOT NULL, subject VARCHAR(150) NOT NULL, content TEXT NOT NULL, state VARCHAR(20) NOT NULL, attempts INT NOT NULL DEFAULT 0, next_run DATETIME(3) NOT NULL, error VARCHAR(255), created_at DATETIME(3) NOT NULL, INDEX(state,next_run));
CREATE TABLE IF NOT EXISTS p1_delivery_receipts (id VARCHAR(64) PRIMARY KEY, channel VARCHAR(12) NOT NULL, destination VARCHAR(150) NOT NULL, subject VARCHAR(150) NOT NULL, content TEXT NOT NULL, mode VARCHAR(20) NOT NULL, expires_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p1_auto_renewals (instance_id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, enabled BOOLEAN NOT NULL, months INT NOT NULL, max_cents BIGINT NOT NULL, authorization VARCHAR(20) NOT NULL, last_cycle VARCHAR(80), last_order_id VARCHAR(64), state VARCHAR(20) NOT NULL, error VARCHAR(255), created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p1_action_previews (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, action VARCHAR(20) NOT NULL, payload TEXT NOT NULL, preview TEXT NOT NULL, state VARCHAR(20) NOT NULL, result TEXT, expires_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p1_provider_configs (id VARCHAR(30) PRIMARY KEY, provider VARCHAR(30) NOT NULL, mode VARCHAR(20) NOT NULL, settings TEXT NOT NULL, version INT NOT NULL, updated_at DATETIME(3) NOT NULL);
CREATE TABLE IF NOT EXISTS p1_provider_qr (payment_id VARCHAR(64) PRIMARY KEY, qr_code TEXT NOT NULL);
